public class ConfigTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        try {
            Config a = Config.getInstance();
            check("getInstance() returns a non-null instance", true, a != null);
            Config b = Config.getInstance();
            check("every getInstance() call returns the same object", true, a != null && a == b);
            a.set("host", "localhost");
            a.set("port", "8080");
            check("get(\"host\")", "localhost", a.get("host"));
            check("settings are visible through the other reference", "8080", b.get("port"));
            a.set("host", "example.com");
            check("set overwrites an existing key", "example.com", b.get("host"));
            check("get of a missing key returns null", null, a.get("does-not-exist"));
        } catch (Exception e) {
            System.out.println("FAIL  unexpected exception -- " + e);
            failures++;
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
